}

private void xrLabel21_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            gjendja = progresiviarketuar - progresivipaguar + gjendjamepare;   

                xrLabel21.Text = String.Format("{0:N2}", gjendja);
}

private void xrLabel11_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            xrLabel11.Text = String.Format("{0:#,#.00}", progresiviarketuar);
}

private void xrLabel9_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            double vleraarketueshme = Convert.ToDouble(GetCurrentColumnValue("vleraarketueshme"));
            double vlerapaguar = Convert.ToDouble(GetCurrentColumnValue("vlerapaguar"));
            if (vleraarketueshme >= 0)
            {
                xrLabel9.Text = String.Format("{0:N2}",vleraarketueshme);
                xrLabel10.Text = String.Format("{0:N2}", 0);
                if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
                    if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                        if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Derdhje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "DERDHJE" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Arketim" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "ARKETIM")
                            progresiviarketuar = progresiviarketuar + vleraarketueshme;
            }
            if (vlerapaguar < 0)
            {
                xrLabel9.Text = String.Format("{0:N2}",Math.Abs(vlerapaguar).ToString());
                xrLabel10.Text = String.Format("{0:N2}", 0);
                if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
                    if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                        if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Terheqje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "TERHEQJE" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Pagese" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "PAGESE")
                            progresiviarketuar = progresiviarketuar + Math.Abs(vlerapaguar);
             }
}

private void xrLabel10_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
        double vleraarketueshme = Convert.ToDouble(GetCurrentColumnValue("vleraarketueshme"));
        double vlerapaguar = Convert.ToDouble(GetCurrentColumnValue("vlerapaguar"));
        if (vlerapaguar >= 0)
        {
            xrLabel10.Text = String.Format("{0:N2}",vlerapaguar);
            xrLabel9.Text = String.Format("{0:N2}", 0);
            if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
                if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                    if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Terheqje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "TERHEQJE" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Pagese" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "PAGESE")
                        progresivipaguar = progresivipaguar + vlerapaguar;
        }
        if (vleraarketueshme < 0)
        {
            xrLabel10.Text = String.Format("{0:N2}",Math.Abs(vleraarketueshme));
            xrLabel9.Text = String.Format("{0:N2}", 0);
            if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
                if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                    if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Derdhje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "DERDHJE" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "Arketim" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString() == "ARKETIM")
                        progresivipaguar = progresivipaguar + Math.Abs(vleraarketueshme);
        }
}

private void xrTableCell32_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (GetCurrentColumnValue("Gjendja") != null)
