                {
                    xrTableCell32.Text = String.Format("{0:N2}", Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString()));
                    gjendjamepare = Convert.ToDouble(GetCurrentColumnValue("Gjendja").ToString());
                }
                else
                {
                    xrTableCell32.Text = " ";

                }
}

