private void xrLabel6_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	XRLabel p = (XRLabel) sender;
	XtraReport report = (XtraReport)p.Report;
	string FilterAvancBanka = (string)report.Parameters["parameterFAB"].Value;
	string FilterAvancArka = (string)report.Parameters["parameterFAA"].Value;

            if (Convert.ToBoolean(GetCurrentColumnValue("LLOJARKABANKA")))
            {
                xrLabel6.Text = FilterAvancBanka  + ":";
            }
            else
            {
                xrLabel6.Text = FilterAvancArka + ":";
            }
}

